 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare relation_n text:=tg_table_schema||'.'||tg_table_name;new_n jsonb;old_n jsonb;ref record;
begin
 new_n:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
