begin
 select coalesce(jsonb_agg(conversation_data_private.operation_row_v1(actual) order by request_id),'[]'::jsonb),count(*) into inventory_n,count_n
  from conversation_data_private.operations_v1 actual where owner_id=u and request_id=any(ids) and request_id<>request_n;
 if count_n<>cardinality(ids) then raise exception 'CONVERSATION_SOURCE_UNAVAILABLE';end if;
 select conversation_data_private.authorities_union_v1(coalesce(jsonb_agg(pair),'[]'::jsonb)) into authorities_n
  from jsonb_array_elements(inventory_n) op cross join lateral jsonb_array_elements(op->'sourceAuthorities') pair;
 if jsonb_array_length(authorities_n)>100 or octet_length(inventory_n::text)>1000000 then raise exception 'CONVERSATION_CAPACITY';end if;
 witness_n:=conversation_data_private.authorities_current_v1(u,authorities_n);
 return jsonb_build_object('graph',conversation_data_private.empty_graph_v1(),'eraseCounts',conversation_data_private.zero_counts_v1('erase'),
  'redactCounts',conversation_data_private.zero_counts_v1('redact'),'retainCounts',conversation_data_private.zero_counts_v1('retain'),'sourceAuthorities',authorities_n,
  'retainedReferences','{"tripIds":[],"memoryIds":[]}'::jsonb,'conflicts','[]'::jsonb,
  'sourceDigest',conversation_data_private.digest_v1(jsonb_build_array(inventory_n,witness_n)::text));
end$function$

turn_private.claim_text_mode(p_owner_id:
CREATE OR REPLACE FUNCTION turn_private.claim_text_mode(p_owner_id uuid, p_policy_id uuid, p_context_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare candidate record; w turn_private.work%rowtype; c turn_private.text_content%rowtype; turn_state text;
begin
  if p_owner_id is null or p_policy_id is null then raise exception 'INVALID_INPUT'; end if;
  for candidate in
    select q.turn_id,q.owner_id,q.session_id from turn_private.work q
    join turn_private.text_content x on x.turn_id=q.turn_id and x.owner_id=q.owner_id
    join turn_private.text_policies p on p.id=x.policy_id
    join turn_private.text_consents s on s.owner_id=x.owner_id and s.policy_id=x.policy_id and s.consent_id=x.consent_id
    where q.owner_id=p_owner_id and q.execution_mode='text' and x.policy_id=p_policy_id and x.hidden_at is null and p.context_mode=p_context_mode
      and p.revoked_at is null and p.effective_at<=clock_timestamp()
      and p.expires_at>clock_timestamp() and p.terms_recheck_at>clock_timestamp() and s.revoked_at is null
      and (q.state='queued' or (q.state='leased' and q.expires_at<=clock_timestamp()))
    order by q.created_at,q.turn_id limit 100
  loop
    if not pg_try_advisory_xact_lock(hashtextextended(candidate.turn_id::text,195)) then continue; end if;
    if not turn_private.lock_turn(candidate.turn_id,candidate.owner_id,candidate.session_id) then
      update turn_private.work set state='cancelled',lease_token=null,expires_at=null
        where turn_id=candidate.turn_id and state in ('queued','leased');
      return jsonb_build_object('kind','empty');
    end if;
    select * into w from turn_private.work where turn_id=candidate.turn_id and owner_id=p_owner_id for update;
    if not found or w.execution_mode<>'text' or w.state not in ('queued','leased') or (w.state='leased' and w.expires_at>clock_timestamp()) then return jsonb_build_object('kind','empty'); end if;
    select * into c from turn_private.text_content where turn_id=w.turn_id and owner_id=p_owner_id and policy_id=p_policy_id and hidden_at is null;
    if not found or not turn_private.text_policy_current(p_policy_id) then return jsonb_build_object('kind','empty'); end if;
    perform 1 from turn_private.text_consents where owner_id=p_owner_id and policy_id=p_policy_id and consent_id=c.consent_id and revoked_at is null for share;
    if not found or not turn_private.text_policy_current(p_policy_id) then return jsonb_build_object('kind','empty'); end if;
    select status into turn_state from public.turns where id=w.turn_id;
    if turn_state in ('completed','proposal_ready','unavailable','failed','cancelled') then perform turn_private.terminal(w.turn_id,'cancelled',w.attempt); return jsonb_build_object('kind','empty'); end if;
    if w.attempt>=w.max_attempts then perform turn_private.terminal(w.turn_id,'quarantined',w.attempt); return jsonb_build_object('kind','empty'); end if;
    update turn_private.work set state='leased',attempt=attempt+1,lease_token=gen_random_uuid(),expires_at=clock_timestamp()+w.lease_ms*interval '1 millisecond'
      where turn_id=w.turn_id returning * into w;
    return jsonb_build_object('kind','leased','turnId',w.turn_id,'ownerId',w.owner_id,'attempt',w.attempt,'leaseToken',w.lease_token,'leaseMs',w.lease_ms);
  end loop;
  return jsonb_build_object('kind','empty');
end $function$

result_data_private.source_member_v1(rel:
CREATE OR REPLACE FUNCTION result_data_private.source_member_v1(relation_n text, v jsonb, refs_n jsonb, jobs_n uuid[])
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare kind_n text;k text;
begin
 kind_n:=case relation_n when 'turn_private.assistant_conversations' then 'conversationIds' when 'turn_private.assistant_goals' then 'goalIds'
  when 'turn_private.assistant_messages' then 'messageIds' when 'turn_private.service_tasks' then 'taskIds' when 'public.turns' then 'turnIds'
  when 'public.chat_threads' then 'threadIds' when 'public.trips' then 'tripIds' when 'public.memory_profiles' then 'memoryIds'
  when 'turn_private.result_artifacts' then 'sourceArtifactIds' when 'public.trip_proposals' then 'proposalIds' end;
 if kind_n is not null and refs_n->kind_n ? (v->>'id') then return case kind_n
  when 'conversationIds' then 'conversations' when 'goalIds' then 'goals' when 'messageIds' then 'messages' when 'taskIds' then 'tasks'
  when 'turnIds' then 'turns' when 'threadIds' then 'threads' when 'tripIds' then 'trips' when 'memoryIds' then 'memories'
  when 'sourceArtifactIds' then 'sourceArtifacts' else 'proposals' end;end if;
 if relation_n='public.model_budget_attempts' and refs_n->'taskIds' ? (v->>'task_id') then return 'budgetAttempts';end if;
 if relation_n='public.model_budget_scopes' and exists(select 1 from turn_private.service_tasks t where refs_n->'taskIds' ? t.id::text and t.budget_scope_id::text=v->>'id'
  union all select 1 from public.model_budget_attempts a where refs_n->'taskIds' ? a.task_id::text and a.scope_id::text=v->>'id') then return 'planningSources';end if;
 if relation_n='public.model_budget_provider_limits' and exists(select 1 from public.model_budget_attempts a where refs_n->'taskIds' ? a.task_id::text and a.scope_id::text=v->>'scope_id' and a.provider=v->>'provider') then return 'planningSources';end if;
 if relation_n='turn_private.planning_v2_execution_profiles' and exists(select 1 from turn_private.planning_v2_execution_runs r where r.turn_id=any(jobs_n) and r.profile_id::text=v->>'id') then return 'planningSources';end if;
 if relation_n='turn_private.planning_v2_registered_tariffs' and exists(select 1 from turn_private.planning_v2_execution_runs r join turn_private.planning_v2_execution_profiles p on p.id=r.profile_id where r.turn_id=any(jobs_n) and p.tariff_id::text=v->>'id') then return 'planningSources';end if;
 if relation_n='turn_private.planning_v2_collector_principals' and exists(select 1 from turn_private.planning_v2_execution_runs r where r.turn_id=any(jobs_n) and r.collector_principal_id::text=v->>'id') then return 'planningSources';end if;

 if relation_n in('turn_private.text_content','turn_private.text_dispatches','turn_private.service_task_turns','turn_private.service_task_capacity','turn_private.work','turn_private.grounded_turns','turn_private.grounded_ai_assist_jobs')
  and (refs_n->'turnIds' ? (v->>'turn_id') or refs_n->'taskIds' ? (v->>'task_id')) then return 'planningSources';end if;
 if relation_n in('turn_private.assistant_travel_intakes','turn_private.assistant_message_source_receipts') and refs_n->'messageIds' ? (v->>'message_id') then return 'planningSources';end if;
 if relation_n in('turn_private.assistant_goal_trip_links','turn_private.assistant_goal_trip_receipts') and refs_n->'goalIds' ? (v->>'goal_id') then return 'planningSources';end if;
 if relation_n in('turn_private.planning_comparisons','turn_private.planning_intake_bindings','turn_private.planning_action_receipts','turn_private.planning_observations','turn_private.planning_model_dispatches','turn_private.planning_v2_place_checkpoints','turn_private.planning_v2_model_attempt_bindings') and v->>'turn_id'=any(jobs_n::text[]) then return 'planningSources';end if;
 return null;
end$function$

public.append_chat_turn_event(p_turn_id:
CREATE OR REPLACE FUNCTION public.append_chat_turn_event(p_turn_id uuid, p_event_id text, p_event_type text, p_state text)
 RETURNS TABLE(sequence integer, state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  turn_row public.turns%rowtype;
  prior_sequence integer;
  prior_state text;
  next_sequence integer;
  terminal_states text[] := array['completed', 'proposal_ready', 'unavailable', 'failed', 'cancelled'];
  states text[] := array['accepted', 'planning', 'retrieving', 'generating', 'validating', 'completed', 'proposal_ready', 'unavailable', 'failed', 'cancelled'];
begin
  select * into turn_row from public.turns where id = p_turn_id and owner_id = (select auth.uid()) for update;
  if not found or turn_row.thread_id is null or not exists (
    select 1 from public.chat_threads where id = turn_row.thread_id and owner_id = (select auth.uid()) and status = 'active'
  ) then raise exception 'FORBIDDEN'; end if;
  if turn_row.status = any(terminal_states) then raise exception 'terminal turn cannot emit events'; end if;
  if (p_event_type = 'terminal') <> (p_state = any(terminal_states)) then raise exception 'invalid terminal event'; end if;
  select e.sequence, e.state into prior_sequence, prior_state from public.chat_turn_events e where e.turn_id = p_turn_id order by e.sequence desc limit 1;
  if prior_sequence is null then raise exception 'turn is missing accepted event'; end if;
  if array_position(states, p_state) < array_position(states, prior_state) then raise exception 'turn state must be monotonic'; end if;
  next_sequence := prior_sequence + 1;
  insert into public.chat_turn_events(owner_id, thread_id, turn_id, event_id, sequence, schema_version, event_type, state)
    values (turn_row.owner_id, turn_row.thread_id, p_turn_id, p_event_id, next_sequence, 'turn-sse-v1', p_event_type, p_state);
  update public.turns set status = p_state, updated_at = now() where id = p_turn_id;
  update public.chat_threads set updated_at = now() where id = turn_row.thread_id;
  return query select next_sequence, p_state;
end;
$function$

export_private.entitlement_commit_progre:
CREATE OR REPLACE FUNCTION export_private.entitlement_commit_progress_v1(j export_private.core_jobs_v1, v jsonb, l uuid, g integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m jsonb;p export_private.entitlement_page_progress_v1%rowtype;
begin
 if jsonb_typeof(v) is distinct from 'array' then return false;end if;select x into m from jsonb_array_elements(v) x where x->>'module'='entitlements';if m is null then return false;end if;
 select * into p from export_private.entitlement_page_progress_v1 where request_id=j.request_id and generation=g and lease_id=l and source_revision=j.entitlement_source_revision;
 if not found then return j.entitlement_source_revision is null and m->'pages'='0'::jsonb and m->'rows'='0'::jsonb and m->>'status' in ('unavailable','failed','partial') and m->>'reason' in ('HANDLER_MISSING','SOURCE_UNAVAILABLE','BOUNDED_LIMIT');end if;
 if m->'pages' is distinct from to_jsonb(p.pages) or m->'rows' is distinct from to_jsonb(p.rows) or export_private.entitlement_source_current_v1(j) is distinct from true then return false;end if;
 if m->>'status'='complete' or m->>'reason'='LIVE_TRAVERSAL' then return p.terminal;end if;return m->>'status'='partial' and m->>'reason' in ('BOUNDED_LIMIT','SOURCE_UNAVAILABLE');
end $function$

export_private.profile_commit_qualifies_:
CREATE OR REPLACE FUNCTION export_private.profile_commit_qualifies_v1(j export_private.core_jobs_v1, modules jsonb, l uuid, g integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare m jsonb;item jsonb;begin
 if export_private.valid_modules_v1(modules,(j.policy_snapshot->>'max_pages')::integer) is not true then return false;end if;
 m:=modules->3;
 if m->'pages'='0' and m->'rows'='0' then return m->>'status' in('unavailable','failed','partial') and m->>'reason' in('HANDLER_MISSING','SOURCE_UNAVAILABLE','BOUNDED_LIMIT');end if;
 if m->>'status' is distinct from 'complete' or m->>'reason' is distinct from 'NONE' or m->'pages' is distinct from '1'::jsonb or m->'rows' is distinct from '1'::jsonb then return false;end if;
 if export_private.live_lease_v1(j,l,g) is not true then return false;end if;
 item:=export_private.profile_source_v1(j.owner_id);
 return notification_private.hash(jsonb_build_object('snapshot',jsonb_build_array(item)))=m->>'digest' and export_private.live_lease_v1(j,l,g);
exception when lock_not_available then return false;end$function$

export_private.memory_commit_progress_v1:
CREATE OR REPLACE FUNCTION export_private.memory_commit_progress_v1(j export_private.core_jobs_v1, v jsonb, p_lease uuid, p_gen integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m jsonb;pages bigint;rows bigint;terminals integer;
begin
 if jsonb_typeof(v) is distinct from 'array' then return false;end if;
 select x into m from jsonb_array_elements(v) x where x->>'module'='memory';if m is null then return false;end if;
 select coalesce(sum(p.pages),0),coalesce(sum(p.rows),0),count(*) filter(where terminal) into pages,rows,terminals from export_private.memory_section_progress_v1 p where p.request_id=j.request_id and p.generation=p_gen and p.lease_id=p_lease and p.source_revision=j.memory_source_revision;
 if m->'pages' is distinct from to_jsonb(pages) or m->'rows' is distinct from to_jsonb(rows) then return false;end if;
 if pages=0 then return j.memory_source_revision is null and m->>'status' in ('unavailable','failed','partial') and m->>'reason' in ('HANDLER_MISSING','SOURCE_UNAVAILABLE','BOUNDED_LIMIT');end if;
 if j.memory_source_revision is null or export_private.memory_source_current_v1(j) is distinct from true then return false;end if;
 if m->>'status'='complete' or m->>'reason'='LIVE_TRAVERSAL' then return terminals=6;end if;
 return m->>'status'='partial' and m->>'reason' in ('SOURCE_UNAVAILABLE','BOUNDED_LIMIT');
end $function$
